#!/bin/bash
# Unattended end-to-end pipeline (planner 7.2). Each stage skips runs that already finished,
# so this script is safe to re-run after an interruption.
#
#   bash run_all.sh [workers]
#
# Stage order: hp (skipped if done) -> g1 -> rest (main, hard, ablation, sensitivity)
#              -> explain SynGT runs -> case study -> report tables
# Do not edit this file while it runs: bash reads it incrementally.
set -u
cd "$(dirname "$0")"
export PYTHONPATH=.
W=${1:-6}
LOG=runs/pipeline.log
mkdir -p runs
say() { echo "[$(date +%H:%M:%S)] $*" | tee -a $LOG; }

say "stage hp";      python -m src.sweep --stage hp --workers "$W" >> $LOG 2>&1
say "stage g1";      python -m src.sweep --stage g1 --workers "$W" >> $LOG 2>&1
say "stage rest (main, hard, ablation, sensitivity)"
python -m src.sweep --stage rest --workers "$W" >> $LOG 2>&1
say "explain";       python -m src.xai.explain_sweep --workers 2 >> $LOG 2>&1
say "case study";    python -m src.eval.case_study >> $LOG 2>&1
say "report";        python -m src.eval.report >> $LOG 2>&1
say "pipeline done"
